import 'package:flutter/material.dart';import 'package:flutter/services.dart';import 'package:flutter_screenutil/flutter_screenutil.dart';import '../../../Core/Resources/app_list.dart';import '../../../Config/Routes/route_name.dart';import '../../../Config/screen_orientation_helper.dart';import '../../../Core/Storage/Local/local_storage_service.dart';import '../../../Core/Storage/Local/local_storage_keys.dart';import '../../../main.dart';import 'loading_splash.dart';import 'background_painter.dart';import 'build_main_details_splash.dart';class SplashBody extends StatefulWidget {  const SplashBody({super.key});  @override  State<SplashBody> createState() => _SplashBodyState();}class _SplashBodyState extends State<SplashBody> {  double logoOpacity = 0.0;  double textOpacity = 0.0;  double loadingOpacity = 0.0;  @override  void initState() {    super.initState();    AppScreenOrientationHelper.lockPortrait();    WidgetsBinding.instance.addPostFrameCallback((_) {      SystemChrome.setSystemUIOverlayStyle(SystemUiOverlayStyle(        statusBarColor: Colors.transparent,        systemStatusBarContrastEnforced: true,        systemNavigationBarContrastEnforced: true,      ));    });    _startAnimations();  }  void _startAnimations() async {    await Future.delayed(Duration(milliseconds: 300));    setState(() => logoOpacity = 1.0);    await Future.delayed(Duration(milliseconds: 300));    setState(() => textOpacity = 1.0);    await Future.delayed(Duration(milliseconds: 300));    setState(() => loadingOpacity = 1.0);    await Future.delayed(Duration(seconds: 1));    _navigateToNextScreen();  }  Future<void> _navigateToNextScreen() async {    final bool isOnboardingCompleted = await LocalStorageService.getValue(      LocalStorageKeys.isOnboardingCompleted,      defaultValue: false,    );    final bool isFirstTime = await LocalStorageService.getValue(      LocalStorageKeys.isFirstTime,      defaultValue: false,    );    if (!isOnboardingCompleted) {      await kNavigationService.clearAndNavigateTo(AppRoutes.boarding);      return;    }    final String nextRoute =        isFirstTime ? AppRoutes.main : AppRoutes.authentication;    await kNavigationService.clearAndNavigateTo(nextRoute);  }  @override  void dispose() {    // SystemChrome.setEnabledSystemUIMode(SystemUiMode.edgeToEdge);    super.dispose();  }  @override  Widget build(BuildContext context) {    return Scaffold(      body: Stack(        clipBehavior: Clip.none,        children: [          ...AppList.gradientColorsBackground,          Positioned.fill(            child: CustomPaint(              painter: BackgroundPainter(),              size: Size.infinite,            ),          ),          Positioned(              right: 0,              left: 0,              top: 188.5.h,              child: AnimatedOpacity(                duration: Duration(milliseconds: 500),                opacity: logoOpacity,                child: LogoAndText(),              )),          Positioned(            right: 0,            left: 0,            bottom: 148.h,            child: AnimatedOpacity(              duration: Duration(milliseconds: 500),              opacity: loadingOpacity,              child: Loading(),            ),          ),        ],      ),    );  }}